codeExample.code:
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
-- FORCE applies the policy to the table owner too. Without it the application
-- role, which usually owns the schema, quietly bypasses everything below.
ALTER TABLE invoices FORCE ROW LEVEL SECURITY;

-- The tenant comes from a session variable the connection pool sets per
-- request, so it cannot be supplied by whoever wrote the query.
CREATE POLICY invoices_tenant_isolation ON invoices
  USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- USING filters reads; WITH CHECK stops a write planting a row under another
-- tenant's id. Policies with only USING are a common half-measure.


-- tests/isolation.sql — run in CI. An isolation rule nobody has tried to
-- break is an assumption, not a control.
BEGIN;
  SET LOCAL app.tenant_id = '11111111-1111-1111-1111-111111111111';
  INSERT INTO invoices (id, tenant_id, total_minor)
    VALUES (gen_random_uuid(), '11111111-1111-1111-1111-111111111111', 5000);

  SET LOCAL app.tenant_id = '22222222-2222-2222-2222-222222222222';

  -- Deliberately no tenant filter: the sloppy query every codebase has.
  DO $$
  BEGIN
    IF (SELECT count(*) FROM invoices) <> 0 THEN
      RAISE EXCEPTION 'cross-tenant read succeeded — isolation is broken';
    END IF;
  END $$;
ROLLBACK;
